def find_initial_picture(pictures, n, m):
    # Find the initial picture by comparing the borders
    for i in range(len(pictures)):
        picture = pictures[i]
        for x in range(1, n-1):
            for y in range(1, m-1):
                if picture[x][y] != picture[x-1][y] and picture[x][y] != picture[x+1][y] and \
                   picture[x][y] != picture[x][y-1] and picture[x][y] != picture[x][y+1]:
                    return i
    return -1

def restore_operations(pictures, n, m, k):
    operations = []
    initial_index = find_initial_picture(pictures, n, m)
    current_picture = pictures[initial_index]

    # Find the indices of the copies
    copy_indices = []
    for i in range(len(pictures)):
        if i != initial_index:
            copy_indices.append(i + 1)

    # Determine the operations
    for i in range(initial_index):
        for x in range(1, n-1):
            for y in range(1, m-1):
                if current_picture[x][y] != current_picture[x-1][y] and current_picture[x][y] != current_picture[x+1][y] and \
                   current_picture[x][y] != current_picture[x][y-1] and current_picture[x][y] != current_picture[x][y+1]:
                    operations.append(f"1 {x+1} {y+1}")
                    current_picture[x][y] = 1 - current_picture[x][y]

    for i in copy_indices:
        operations.append(f"2 {i}")

    return initial_index + 1, len(operations), operations

